window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["citations"]={"title":"引用与证据对齐：把每个可核查主张连接到最小充分原文","subtitle":"从原子主张、稳定锚点和蕴含判断，到引用正确性、完整性与来源质量，建立真正可核验的回答。","thesis":"引用系统的核心不是生成链接，而是建立<b>主张—证据跨度—来源版本</b>的可验证映射；“引用真实存在”与“证据支持这句话”是两种完全不同的性质。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"四条主张、三个引用","rule":"按主张计","steps":"引用正确性=2/3","interpretation":"不能互相替代"}}],"formulas":[{"id":"citation-quality-coverage","section":3,"formulaIndex":1,"symbols":[{"name":"CitationPrecision","meaning":"已给引用中真正支持相邻主张的比例","evidence":"输出 CitationPrecision"},{"name":"NsupportedCitation","meaning":"正确支持主张的已给引用数量","evidence":"正确支持引用数 NsupportedCitation"},{"name":"Ncitation","meaning":"回答中全部已给引用数量","evidence":"全部已给引用数 Ncitation"},{"name":"Coverage","meaning":"全部应引主张中得到正确支持的比例","evidence":"Coverage"},{"name":"NcoveredClaim","meaning":"获得正确证据支持的应引主张数","evidence":"被正确支持主张数 NcoveredClaim"},{"name":"Nclaim","meaning":"回答中全部应引用主张数","evidence":"应引用主张数 Nclaim"}]}],"termReviews":[{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"蕴含","meaning":"证据内容在语义和限定条件上足以推出主张","purpose":"区分真正支持与仅仅主题相关的材料","definitionEvidence":"蕴含是“证据内容足以推出该主张”","purposeEvidence":"而不只是主题相近"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"引用是原子主张到版本化原文跨度的可验证映射。","evidence":"引用是映射关系，不是答案装饰"},"problem":{"answer":"它防止段末堆链接却没有一句主张真正被支持。","evidence":"为什么可能一句都没被支持"},"inputOutput":{"answer":"输入主张白名单和跨度，输出可点击证据映射。","evidence":"输出主张到版本化原文的可点击映射"},"mechanism":{"answer":"从白名单选择证据 ID，再由渲染层生成定位链接。","evidence":"跨度在语义上蕴含主张才算支持"},"interpretation":{"answer":"文档或链接存在不等于其内容支持相邻主张。","evidence":"只证明文档可定位"},"boundary":{"answer":"无白名单证据时应删减降格或拒答，不能编链接。","evidence":"而不是补一个主题相关链接"}},{"section":2,"definition":{"answer":"原子主张是能够独立判断真假的最小回答断言。","evidence":"先把复合句拆成原子主张"},"problem":{"answer":"它避免一个引用被误认为同时支持速度准确率和成本。","evidence":"需要几个证据"},"inputOutput":{"answer":"输入复合回答，输出原子主张及引用或推断类型。","evidence":"输出可分别判断真假的原子主张"},"mechanism":{"answer":"拆分数字比较因果归因，并为每条绑定最小证据。","evidence":"每条只绑定最小充分证据"},"interpretation":{"answer":"连接词可能引入额外因果或推断主张。","evidence":"“因为”还引入因果主张"},"boundary":{"answer":"建议可不引用，但事实前提仍必须有证据。","evidence":"支撑建议的事实前提仍需引用"}},{"section":3,"definition":{"answer":"引用正确性衡量已给链接质量，覆盖率衡量应引主张覆盖。","evidence":"完整示例：计算引用正确性与完整性"},"problem":{"answer":"它区分引用有多少是真的与回答还有多少主张缺证。","evidence":"怎样判断系统到底做得好不好"},"inputOutput":{"answer":"输入四类计数，输出 CitationPrecision 与 Coverage。","evidence":"输出 CitationPrecision 与 Coverage"},"mechanism":{"answer":"分别以全部引用和全部应引主张作为分母计算。","evidence":"前者等于 NsupportedCitation/Ncitation"},"interpretation":{"answer":"六十六点七与五十表示不同缺陷，不能互相替代。","evidence":"分别说明已给链接质量和应引主张覆盖"},"boundary":{"answer":"主题相近不构成蕴含，必须足以推出具体主张。","evidence":"而不只是主题相近"}},{"section":4,"definition":{"answer":"稳定引用锚点由规范文档版本和原始跨度构成。","evidence":"证据锚点要经得住切块、更新与重排"},"problem":{"answer":"它防止重新切块或网页更新后旧引用跳错位置。","evidence":"旧引用为什么会跳错位置"},"inputOutput":{"answer":"输入文档版本和坐标，输出跨更新仍可定位的引用。","evidence":"输出跨切块更新仍可定位的引用"},"mechanism":{"answer":"块 ID 映射到原始页章节字符或版面坐标。","evidence":"引用必须映射回原始版本坐标"},"interpretation":{"answer":"chunk ID 是索引产物，不是永久证据身份。","evidence":"chunk ID 只是索引产物"},"boundary":{"answer":"旧版本无法定位时必须明确标记链接漂移。","evidence":"不能悄悄跳到新文档首页"}},{"section":5,"definition":{"answer":"证据闭环先选择证据，再生成主张并逐条核验。","evidence":"原创图：生成前选择证据，生成后逐主张核验"},"problem":{"answer":"它防止先写答案再按主题补出伪引用。","evidence":"为什么“先写答案再补链接”特别容易制造伪引用"},"inputOutput":{"answer":"输入问题证据和主张，输出二部图与定位链接。","evidence":"输出主张—证据二部图、蕴含完整性检查及定位链接"},"mechanism":{"answer":"生成前限定白名单，生成后检查每条主张的蕴含和覆盖。","evidence":"生成后逐主张核验"},"interpretation":{"answer":"主张证据二部图比文字加链接更可审计。","evidence":"能发现缺证和错配"},"boundary":{"answer":"验证失败主张必须删除、降格或继续补查。","evidence":"必须删除、降格或补查"}},{"section":6,"definition":{"answer":"引用验证分为证据蕴含、来源适用和事实可信三层。","evidence":"蕴含、来源质量与事实真值要分别判断"},"problem":{"answer":"它处理低质量文章确实写了某话但事实仍可能错误。","evidence":"这个引用算正确吗"},"inputOutput":{"answer":"输入主张跨度来源与独立证据，输出三层判断。","evidence":"输出蕴含判断、来源适用性和事实可信度三个结果"},"mechanism":{"answer":"先查语义支持，再查来源范围，最后交叉核实事实。","evidence":"文章确实声称 X 只证明归因忠实"},"interpretation":{"answer":"忠实归因不等于被归因的说法真实。","evidence":"不能证明 X 为真"},"boundary":{"answer":"自动蕴含在否定范围表格跨句上需要人工抽检。","evidence":"自动蕴含模型只能筛查，否定词、表格、范围限定和跨句推断仍需人工抽检"}},{"section":7,"definition":{"answer":"冲突证据处理保留不同来源及其口径时间和适用范围。","evidence":"冲突证据不能被静默平均"},"problem":{"answer":"它回答两个可信来源给出不同数字时如何呈现。","evidence":"模型该选哪个"},"inputOutput":{"answer":"输入来源差异，输出裁决选择或并列冲突说明。","evidence":"输出可裁决选择或并列展示的冲突说明"},"mechanism":{"answer":"先核对范围版本，无法裁决时并列并说明条件。","evidence":"仍冲突则保留双方及适用条件"},"interpretation":{"answer":"检索排名靠前不能替代来源权威与口径判断。","evidence":"检索名次不能代替来源裁决"},"boundary":{"answer":"综合推断必须标明来源，不能伪装成原话。","evidence":"不能伪装成某一来源原话"}},{"section":8,"definition":{"answer":"引用界面把标记摘录来源日期和原文定位一起呈现。","evidence":"引用界面也是验证系统的一部分"},"problem":{"answer":"它确保用户实际能够检查证据而不是只到首页。","evidence":"用户点开后只到文档首页，是否算可核验"},"inputOutput":{"answer":"输入主张锚点权限，输出就近标记和高亮原句。","evidence":"输出紧邻标记、悬停摘要及点击高亮原句"},"mechanism":{"answer":"按主张范围展示最小摘录并跳转对应版本坐标。","evidence":"用户能回到支持跨度才算可核验"},"interpretation":{"answer":"首页链接无法证明特定主张所依据的具体内容。","evidence":"跳到首页不够"},"boundary":{"answer":"摘录须满足版权最小充分原则并说明访问限制。","evidence":"受限来源应明确访问限制"}},{"section":9,"definition":{"answer":"引用评测由人工金标主张证据蕴含和来源质量建立。","evidence":"评测要有人标主张，也要测定位是否真的可用"},"problem":{"answer":"它解释 URL 返回成功为何不足以验收引用。","evidence":"自动检查 URL 200，为什么远远不够"},"inputOutput":{"answer":"输入人工金标，输出正确完整定位冲突和任务指标。","evidence":"输出正确性、完整性、错位率、来源层级、冲突覆盖及任务质量"},"mechanism":{"answer":"逐主张比较定位跨度和语义支持并测试无证拒答。","evidence":"还要测试无足够证据时是否拒绝"},"interpretation":{"answer":"URL 可访问只证明资源存在，不证明定位或支持。","evidence":"不证明定位或支持正确"},"boundary":{"answer":"数字日期因果表格和多跳必须分别切片。","evidence":"数字、日期、因果、表格和多跳推断需分别切片"}},{"section":11,"definition":{"answer":"检索、引用、归因和事实核查是四道不同质量关。","evidence":"先澄清：检索、引用、归因与事实核查是四道不同关"},"problem":{"answer":"它解释找到正确论文后答案为何仍可能不可靠。","evidence":"为何仍可能写出不可靠答案"},"inputOutput":{"answer":"输入材料跨度表述和核查证据，输出四关状态。","evidence":"输出四道关分别通过或失败的状态"},"mechanism":{"answer":"依次检查找到材料、连接跨度、忠实归因和事实可信。","evidence":"检索负责找材料，引用负责连接跨度"},"interpretation":{"answer":"grounded 单标签会掩盖各层不同的失败原因。","evidence":"一个 grounded 标签不能覆盖四层"},"boundary":{"answer":"解释必须显式给出推断步骤、条件与不确定性。","evidence":"必须显式给出推断步骤和不确定性"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>把回答拆成需要引用的原子主张；计算引用正确性与完整性；设计稳定锚点和证据白名单；处理冲突来源、推断与版权边界。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>引用是映射关系，不是答案装饰<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">段末放三个链接，为什么可能一句都没被支持？</p><p>一个链接只证明文档存在；正确引用还要求文档中的特定跨度在语义上支持相邻主张。系统需保留文档身份、版本、页码/段落与字符跨度，让读者能跳回原句。模型不得凭记忆生成 URL，而应从检索白名单选择证据 ID，由渲染层生成链接。</p><p>引用对齐输入原子主张、证据白名单和稳定文档跨度，输出主张到版本化原文的可点击映射。链接存在只证明文档可定位，跨度在语义上蕴含主张才算支持；模型不能凭记忆编 URL。没有白名单证据时应删除、降格或拒答，而不是补一个主题相关链接。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>先把复合句拆成原子主张<span class=\"dd-badge eng\">主张</span></h2><p class=\"dd-lead\">“模型更快、更准且成本下降30%”需要几个证据？</p><p>至少拆成速度、准确率、成本变化三条可独立为真假的主张；数字、日期、归因、因果和比较通常需要引用。连接词会隐藏额外断言：“因为”需要因果证据，“因此”可能是作者推断。主观建议可不引用，但其事实前提仍要引用，并明确区分来源陈述与系统推断。</p><p>主张拆分输入回答中的复合句，输出可分别判断真假的原子主张及“需引用、推断或建议”类型。速度、准确率和成本是三条独立主张，“因为”还引入因果主张；每条只绑定最小充分证据。主观建议可以不引，但支撑建议的事实前提仍需引用。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：计算引用正确性与完整性<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">四条主张、三个引用，怎样判断系统到底做得好不好？</p><p>回答含四条应引用主张 C1–C4。引用 E1 支持 C1，E2 只与 C2 主题相关但不蕴含，E3 支持 C3，C4 没引用。按主张计：三个已给引用中两个正确，引用正确性=2/3≈<b>66.7%</b>；四个应引用主张中两个得到正确支持，完整性=2/4=<b>50%</b>。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"引用正确性与应引主张覆盖率\"><mi>CitationPrecision</mi><mo>=</mo><mfrac><mi>NsupportedCitation</mi><mi>Ncitation</mi></mfrac><mo>;</mo><mi>Coverage</mi><mo>=</mo><mfrac><mi>NcoveredClaim</mi><mi>Nclaim</mi></mfrac></math></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>主张</th><th>证据</th><th>判断</th><th>原因</th></tr></thead><tbody><tr><td>C1 发布于周一</td><td>E1日期行</td><td>支持</td><td>直接蕴含</td></tr><tr><td>C2 成本降30%</td><td>E2价格首页</td><td>不支持</td><td>无30%对比</td></tr><tr><td>C3 样本为500</td><td>E3方法段</td><td>支持</td><td>直接数字</td></tr><tr><td>C4 优于基线</td><td>无</td><td>缺失</td><td>未给比较证据</td></tr></tbody></table></div><p>指标案例输入应引用主张数 Nclaim、全部已给引用数 Ncitation、正确支持引用数 NsupportedCitation 和被正确支持主张数 NcoveredClaim，输出 CitationPrecision 与 Coverage。这里的蕴含是“证据内容足以推出该主张”，而不只是主题相近；前者等于 NsupportedCitation/Ncitation，后者等于 NcoveredClaim/Nclaim。66.7% 与 50% 分别说明已给链接质量和应引主张覆盖，不能互相替代。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>证据锚点要经得住切块、更新与重排<span class=\"dd-badge eng\">数据契约</span></h2><p class=\"dd-lead\">文档重新切块后，旧引用为什么会跳错位置？</p><p>chunk ID 只是索引产物，不应成为永久引用。保存规范文档 ID、内容版本或哈希、原始页码/章节、字符跨度和摘录；切块只保存到这些锚点的映射。网页更新时保留抓取时间与快照标识，无法定位旧版本就明确标注链接漂移。</p><p>PDF 表格、脚注与 OCR 需要版面坐标或结构路径，纯文本偏移不足以还原视觉上下文。引用点击失败本身应成为监控指标。</p><p>稳定锚点输入规范文档 ID、内容版本或哈希、页章节、字符或版面跨度和摘录，输出跨切块更新仍可定位的引用。chunk ID 只是索引产物，重新切块后会改变；引用必须映射回原始版本坐标。旧版本无法定位时要明确标记漂移，不能悄悄跳到新文档首页。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：生成前选择证据，生成后逐主张核验<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">为什么“先写答案再补链接”特别容易制造伪引用？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 310\" role=\"img\" aria-label=\"用户问题经过证据检索和原子主张生成形成主张证据二部图，再经蕴含完整性和来源质量验证后渲染定位链接\"><defs><marker id=\"c27a\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"18\" y=\"112\" width=\"108\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"72\" y=\"142\" text-anchor=\"middle\" class=\"svg-t\">问题</text><text x=\"72\" y=\"164\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">引用要求</text><path d=\"M126,148 L178,92\" stroke=\"#788293\" marker-end=\"url(#c27a)\"/><path d=\"M126,148 L178,207\" stroke=\"#788293\" marker-end=\"url(#c27a)\"/><rect x=\"183\" y=\"48\" width=\"155\" height=\"88\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"260\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\">证据白名单</text><text x=\"260\" y=\"102\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">稳定ID · 版本 · 跨度</text><text x=\"260\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">来源质量 / 时间</text><rect x=\"183\" y=\"173\" width=\"155\" height=\"88\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"260\" y=\"202\" text-anchor=\"middle\" class=\"svg-t\">原子主张</text><text x=\"260\" y=\"227\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">事实 / 数字 / 归因</text><text x=\"260\" y=\"247\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">推断明确标注</text><path d=\"M338,92 L400,136\" stroke=\"#788293\" marker-end=\"url(#c27a)\"/><path d=\"M338,217 L400,168\" stroke=\"#788293\" marker-end=\"url(#c27a)\"/><rect x=\"405\" y=\"88\" width=\"145\" height=\"128\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"477\" y=\"118\" text-anchor=\"middle\" class=\"svg-t\">主张—证据图</text><text x=\"477\" y=\"145\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">蕴含正确性</text><text x=\"477\" y=\"169\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">应引完整性</text><text x=\"477\" y=\"193\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">冲突 / 时效 / 权威</text><path d=\"M550,152 L600,152\" stroke=\"#788293\" marker-end=\"url(#c27a)\"/><rect x=\"605\" y=\"88\" width=\"112\" height=\"128\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"661\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\">渲染</text><text x=\"661\" y=\"146\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">就近标记</text><text x=\"661\" y=\"169\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">点击原句</text><text x=\"661\" y=\"193\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">缺证据降格</text></svg><figcaption>图 1　答案不是“文字+链接”，而是可审计的主张—证据二部图。</figcaption></figure><p>证据闭环输入问题、白名单证据和原子主张，输出主张—证据二部图、蕴含完整性检查及定位链接。先选证据再生成能限制模型只用可用材料，生成后逐主张核验能发现缺证和错配；先写答案再补链接容易按主题凑引用。验证失败的主张必须删除、降格或补查。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>蕴含、来源质量与事实真值要分别判断<span class=\"dd-badge eng\">三层验证</span></h2><p class=\"dd-lead\">一篇低质量文章确实写了某句话，这个引用算正确吗？</p><p>从对齐角度，它可能忠实支持“该文章声称X”；从事实角度，X仍可能错。验证应分三层：证据是否蕴含主张、来源是否适合该主张、多个独立来源是否共同支持事实。优先一手资料、原始研究和正式记录，并检查发布日期、样本与适用范围。</p><p>自动蕴含模型只能筛查，否定词、表格、范围限定和跨句推断仍需人工抽检。</p><p>三层验证输入主张、支持跨度、来源属性和独立事实证据，输出蕴含判断、来源适用性和事实可信度三个结果。文章确实声称 X 只证明归因忠实，不能证明 X 为真；一手资料也可能只适用于特定样本和时间。自动蕴含模型只能筛查，否定、范围、表格和跨句推断需人工抽检。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>冲突证据不能被静默平均<span class=\"dd-badge eng\">冲突</span></h2><p class=\"dd-lead\">两个可信来源给出不同数字时，模型该选哪个？</p><p>先检查口径、时间、版本和群体是否不同；若仍冲突，并列呈现各自主张、证据和适用条件，说明无法裁决。不能因为某段排在检索第一就隐藏另一来源。需要综合推断时明确写“根据A与B推断”，不要伪装成任一来源原话。</p><p>冲突处理输入多个来源的数字、口径、时间、版本、群体和权威信息，输出可裁决选择或并列展示的冲突说明。先检查是否其实描述不同范围，仍冲突则保留双方及适用条件；检索名次不能代替来源裁决。综合推断必须标明由哪些来源推得，不能伪装成某一来源原话。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>引用界面也是验证系统的一部分<span class=\"dd-badge eng\">交互</span></h2><p class=\"dd-lead\">用户点开后只到文档首页，是否算可核验？</p><p>标记应紧邻主张，悬停显示短摘录、来源和日期，点击定位原句并高亮上下文。多个主张共用证据时仍要明确范围；同一主张需要多源时并列。移动端也必须可展开，不能让引用只在桌面 hover 可见。</p><p>摘录保持最小充分上下文，避免过量复制受版权保护内容；对付费或受限来源说明访问限制，不用无法公开核验的摘录冒充开放证据。</p><p>引用界面输入主张、最小摘录、来源日期、定位锚点和访问权限，输出紧邻标记、悬停摘要及点击高亮原句。用户能回到支持跨度才算可核验，跳到首页不够；移动端也必须可展开。摘录受最小充分和版权边界约束，受限来源应明确访问限制。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要有人标主张，也要测定位是否真的可用<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">自动检查 URL 200，为什么远远不够？</p><p>建立人工标注集：拆分应引主张、标最小充分证据、蕴含关系和来源质量。分别报告引用正确性、完整性、无效/错位锚点率、来源层级、冲突覆盖与答案任务质量；按数字、日期、因果、表格和多跳推断切片。</p><p>还要测“无足够证据时是否拒绝或降格”。强迫每个问题生成带引答案会提高形式覆盖，却制造更隐蔽的伪引用。</p><p>引用评测输入人工拆分主张、金标证据、蕴含和来源质量，输出正确性、完整性、错位率、来源层级、冲突覆盖及任务质量。URL 返回 200 只证明资源可访问，不证明定位或支持正确；还要测试无足够证据时是否拒绝。数字、日期、因果、表格和多跳推断需分别切片。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">真实链接可以支撑错误答案，正确答案也可能缺少可核验证据。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>有链接就有依据</td><td>要核对具体跨度是否蕴含主张</td></tr><tr><td>引用越多越可靠</td><td>冗余弱来源会掩盖核心缺证</td></tr><tr><td>相似段落就是证据</td><td>主题相关不等于语义支持</td></tr><tr><td>段末引用支持整段</td><td>复合段落需拆原子主张</td></tr><tr><td>来源写了就是真</td><td>蕴含与事实可信度是不同层次</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>检索、chunking、信息抽取</td></tr><tr><td><b>本页核心</b></td><td>原子主张、稳定锚点、蕴含、完整性</td></tr><tr><td>相邻</td><td>RAG、知识图谱、幻觉与评测</td></tr><tr><td>工程</td><td>版本快照、定位UI、版权与访问控制</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>先澄清：检索、引用、归因与事实核查是四道不同关<span class=\"dd-badge intuition\">概念消歧</span></h2><p class=\"dd-lead\">系统找到了正确论文，为何仍可能写出不可靠答案？</p><p><b>检索</b>只把候选材料带进上下文；<b>引用</b>把主张连到某个跨度；<b>归因</b>忠实表达“谁说了什么”；<b>事实核查</b>再判断该说法是否可信。系统可能检索到正确论文，却把实验组数字写成对照组；也可能准确引用一篇已撤稿论文。四道关要分别记录通过/失败，不能用一个“grounded”标签掩盖。</p><p>还要区分<b>证据</b>与<b>解释</b>：证据是可定位材料，解释是基于材料的综合。解释可以有价值，但必须标出推断步骤、适用条件和不确定性。对于“没有显著差异”这类统计结论，不能只引用摘要中“结果不显著”的邻近句，还要核对比较对象、指标、置信区间与样本。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>失败</th><th>表面现象</th><th>应修哪一层</th></tr></thead><tbody><tr><td>没找到关键文档</td><td>答案缺证</td><td>检索召回</td></tr><tr><td>引用到邻近数字</td><td>链接真实但不支持</td><td>跨度/蕴含</td></tr><tr><td>把作者假设写成结论</td><td>归因失真</td><td>主张类型</td></tr><tr><td>只用过时二手来源</td><td>有支持仍可能错</td><td>来源与事实核查</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>初学者最易混淆：</b>“答案有引用”最多说明存在一条链接；只有主张拆分、跨度蕴含、来源质量和冲突检查都通过，才接近可核验。</div><p>概念辨析输入检索结果、引用跨度、归因表述和事实核查证据，输出四道关分别通过或失败的状态。检索负责找材料，引用负责连接跨度，归因负责忠实表达谁说什么，事实核查判断说法是否可信；一个 grounded 标签不能覆盖四层。解释是基于证据的综合，必须显式给出推断步骤和不确定性。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>识别答案中应引用的原子主张</li><li>从白名单检索候选证据</li><li>保留文档版本与最小跨度</li><li>判断证据是否蕴含主张</li><li>检查来源质量、时间与冲突</li><li>缺证据则删除/降格/拒答</li><li>渲染就近且可定位的引用</li><li>抽样复核正确性与完整性</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>引用正确性与完整性有什么不同？</li><li>为什么不能用 chunk ID 作永久锚点？</li><li>主题相关为何不等于证据支持？</li><li>来源蕴含主张是否证明事实为真？</li><li>没有充分证据时系统应怎样做？</li><li>假设“引用与证据对齐：把每个可核查主张连接到最小充分原文”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>正确性看已给引用是否支持，完整性看所有应引主张是否获得正确支持。</li><li>重新切块会改变ID，需要映射到文档版本和原始跨度。</li><li>段落可能谈同一主题，却没有蕴含具体数字、比较或因果。</li><li>不一定，还要判断来源质量、时效与独立证据。</li><li>删除主张、明确降格为推断或拒答，不能编造引用。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2305.14627\" target=\"_blank\" rel=\"noopener\">ALCE</a>：带引用长文本生成与评测</li><li><a href=\"https://arxiv.org/abs/2305.14251\" target=\"_blank\" rel=\"noopener\">FActScore</a>：原子事实层面的细粒度评估</li><li><a href=\"https://arxiv.org/abs/2005.11401\" target=\"_blank\" rel=\"noopener\">Retrieval-Augmented Generation</a>：检索增强生成基础</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
